            if ((int >= worker.argv.len)) {
                return "";
            }
            return self.base.interpreter.getVmArgsUtf8(worker.argv, int);
        }
        const argv = vm.argv;
        if ((int >= argv.len)) {
            return "";
        }
        return argv[@as(usize, @intCast(int))];
},
.mini => {
const ctx = self.base.interpreter.command_ctx;
        if ((int >= (1 + ctx.passthrough.len))) {
            return "";
        }
        if ((int == 0)) {
            return ctx.positionals[@as(usize, @intCast(((ctx.positionals.len - 1) - int)))];
        }
        return ctx.passthrough[@as(usize, @intCast((int - 1)))];
},
}
}

pub fn currentWord(self: *Expansion) *const ast.SimpleAtom {
        return (switch (self.node) {
.simple => (&self.node.simple),
.compound => (&self.node.compound.atoms[@as(usize, @intCast(self.word_idx))]),
});
}

pub fn expansionSizeHint(self: *Expansion, atom: *const ast.Atom, has_unknown: *bool) usize {
        return (switch (std.meta.activeTag(atom.*)) {
.simple => self.expansionSizeHintSimple((&atom.simple), has_unknown),
.compound => {
{
            if (atom.compound.brace_expansion_hint) {
                has_unknown.* = true;
            }
            var out: usize = 0;
            _ = &out;
            for (cp_iter_slice(atom.compound.atoms)) |simple| {
                _ = &simple;
                out = (out + self.expansionSizeHintSimple((&simple), has_unknown));
            }
            return out;
        }
},
});
}

pub fn expansionSizeHintSimple(self: *Expansion, simple: *const ast.SimpleAtom, has_unknown: *bool) usize {
        return (switch (simple.*) {
.Text => |txt| txt.len,
.quoted_empty => 0,
.Var => |label| self.expandVar(label).len,
.VarArgv => |int| self.expandVarArgv(int).len,
.brace_begin, .brace_end, .comma, .asterisk => 1,
.double_asterisk => 2,
.cmd_subst => {
{
            has_unknown.* = true;
            return 0;
        }
},
.tilde => {
{
            has_unknown.* = true;
            return 0;
        }
},
});
}

pub fn outEnsureUnusedCapacity(self: *Expansion, additional: usize) void {
        switch (self.out) {
.array_of_ptr => {
_ = bun.handleOom(self.out.array_of_ptr.ensureUnusedCapacity(additional));
},
.array_of_slice => {
_ = bun.handleOom(self.out.array_of_slice.ensureUnusedCapacity(additional));
},
.single => {

},
}
}
